CREATE TEMP TABLE task_migration_frozen_rows (name text PRIMARY KEY, payload jsonb NOT NULL);
DO $verify960$ DECLARE fixture record; actual jsonb; expected jsonb; BEGIN
  FOR fixture IN SELECT name,payload FROM pg_temp.task_migration_frozen_rows LOOP
    EXECUTE format('SELECT jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text) FROM %I t', fixture.name) INTO actual;
    SELECT jsonb_agg(value ORDER BY value::text) INTO expected FROM jsonb_array_elements(fixture.payload);
    IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Frozen historical facts differ for %', fixture.name; END IF;
  END LOOP;
END $verify960$;
